const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let entries=[],manifests=new Map(),current=null,selectedId='',matched='',verdict='',misses=[],logMode='answers';
async function api(path,body){const r=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {ok:r.ok,status:r.status,data:await r.json()}}
function groups(e){const m=new Map();for(const f of e.closure){const key=f.path.includes('/')?f.path.slice(0,f.path.lastIndexOf('/')):'Bundle root';if(!m.has(key))m.set(key,[]);m.get(key).push(f)}return [...m]}
function display(v,reason,metrics=''){verdict=v;$('#verdict').textContent=v;$('#reason').textContent=reason;$('#metrics').textContent=metrics}
function node(id,x,y,w,label,sub,cls=''){const text=label.length>25?label.slice(0,23)+'…':label;return `<g class="node ${cls}" data-node="${esc(id)}" tabindex="0" role="button" aria-label="${esc(label+' / '+sub)}"><title>${esc(label+' / '+sub)}</title><rect x="${x}" y="${y}" width="${w}" height="52" rx="3"/><text x="${x+10}" y="${y+22}">${esc(text)}</text><text class="sub" x="${x+10}" y="${y+40}">${esc(sub)}</text></g>`}
function draw(){let ns='',es='';const hubs=[...new Set(entries.flatMap(s=>{const e=manifests.get(s.id);return e?[...e.requires,e.toolchain]:[s.toolchain]}).filter(Boolean))];const n=Math.max(entries.length,1),row=122,height=Math.max(n*row+95,hubs.length*78+75);const edge=(x,y,xx,yy,lit)=>`<path class="edge ${lit?'lit':''}" d="M${x} ${y} C${(x+xx)/2} ${y},${(x+xx)/2} ${yy},${xx} ${yy}"/>`;
entries.forEach((s,i)=>{const e=manifests.get(s.id),y=50+i*row,lit=matched===s.id,sel=selectedId===s.id;ns+=node('entry:'+s.id,12,y,178,s.id,s.replay_status==='recorded'?'Recorded / not re-run':s.kind,sel?'selected':lit?'active':'');const subject=e?.subject||s.subject;ns+=node('entry:'+s.id,242,y,170,subject?.artifact?.name||subject?.name||s.title,subject?.artifact?'Artifact / SHA-256':'Subject',lit?'active':'');es+=edge(190,y+26,242,y+26,lit);if(e){const gs=groups(e);ns+=node('files:'+s.id,462,y,178,e.closure.length+' closure files',gs.length+' directory groups',lit?'active':'');es+=edge(412,y+26,462,y+26,lit);[...e.requires,e.toolchain].forEach(r=>{es+=edge(640,y+26,750,52+hubs.indexOf(r)*78+26,lit)});if(e.check){ns+=node('check:'+s.id,242,y+59,170,sel&&['ACCEPT','REJECT'].includes(verdict)?(verdict==='ACCEPT'?'✓ ACCEPT':'× REJECT'):'Input checker','Checks caller input',sel&&verdict==='ACCEPT'?'accept':sel&&verdict==='REJECT'?'reject':lit?'active':'');es+=edge(190,y+26,242,y+85,lit)}}else{ns+=node('entry:'+s.id,462,y,178,'Manifest unavailable','Mock summary only');if(s.toolchain)es+=edge(640,y+26,750,52+hubs.indexOf(s.toolchain)*78+26,false)}});
hubs.forEach((h,i)=>{const e=manifests.get(matched),lit=e&&[...e.requires,e.toolchain].includes(h);ns+=node('hub:'+i,750,52+i*78,190,h.replace('leanprover/',''),h.includes('lean4:')?'Toolchain':'Required library','hub '+(lit?'active':''))});const bottom=Math.max(height,entries.length*row+60);misses.forEach((m,i)=>ns+=node('demand',12+(i%3)*245,bottom+Math.floor(i/3)*70,225,m,'Demand / no match','miss'));$('#graph').innerHTML=`<svg viewBox="0 0 960 ${bottom+Math.max(1,Math.ceil(misses.length/3))*70+5}" aria-label="All library entries and shared dependencies"><title>Proof dependency graph</title><text x="12" y="22" font-size="12" fill="#22364b">Entry</text><text x="242" y="22" font-size="12" fill="#22364b">Subject / artifact</text><text x="462" y="22" font-size="12" fill="#22364b">Delivered closure</text><text x="750" y="22" font-size="12" fill="#22364b">Shared requirements</text>${es}${ns}</svg>`;$('#count').textContent=entries.length+' entries / '+hubs.length+' shared requirements';$('#textgraph').innerHTML='<ul>'+entries.map(s=>{const e=manifests.get(s.id);return `<li><button data-select="${esc(s.id)}">${esc(s.id)}</button>: ${esc(s.claim)}<br>${e?esc([e.subject.name,e.closure.length+' files',...e.requires,e.toolchain].join('; ')):'Manifest unavailable in this mock.'}</li>`}).join('')+'</ul>'+misses.map(m=>`<p>Dangling demand: ${esc(m)}</p>`).join('');document.querySelectorAll('[data-node]').forEach(el=>{const act=async()=>{const [kind,...rest]=el.dataset.node.split(':'),id=rest.join(':');if(kind==='demand')return logs('demand');if(kind==='hub'){$('#notice').textContent='Shared requirement: '+hubs[+id];return}if(id!==selectedId)await select(id);if(kind==='files'){openDossier();$('.files')?.scrollIntoView({block:'start'})}if(kind==='check')$('#input').focus()};el.onclick=()=>act().catch(failure);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act().catch(failure)}}});document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>select(b.dataset.select).catch(failure))}
function renderEvidence(e){$('#evidence').innerHTML=`<h3>${esc(e.title)}</h3><p>${esc(e.claim)}</p>${e.replay.status==='recorded'?'<p class="warning"><b>Recorded stub. Not re-run by fvapi.</b> The transcript comes from an earlier run.</p>':'<p>Real replay available. Re-run the bundle to establish your own result.</p>'}<a href="/v0/bundles/${encodeURIComponent(e.id)}.tar.gz">Download proof bundle</a><div class="evidence-grid"><div><h4>Statements to match</h4>${e.statements.map(s=>`<p>${esc(s.name)}<br>${esc(s.file)}:${s.line}</p><pre>${esc(s.text)}</pre>`).join('')}<div class="files"><h4>Delivered closure / ${e.closure.length} files</h4>${groups(e).map(([dir,fs])=>`<details><summary>${esc(dir)} / ${fs.length} files</summary>${fs.map(f=>`<div class="file"><b>${esc(f.path)}</b><br>${f.bytes} bytes<code>sha256 ${esc(f.sha256)}</code></div>`).join('')}</details>`).join('')}</div></div><div><h4>Replay command</h4><pre id="command">${esc(e.replay.command)}</pre><button id="copy">Copy replay command</button><p>${esc(e.replay.note)}</p><h4>Expected axioms</h4><pre>${esc(e.replay.expect_axioms.join('\n')||'None')}</pre>${e.replay.transcript?`<details><summary>Recorded transcript / not re-run</summary><pre>${esc(e.replay.transcript)}</pre></details>`:''}<h4>Licence and source</h4><dl><dt>Licence</dt><dd>${esc(e.licence.spdx)}</dd><dt>Third-party notices</dt><dd>${e.licence.third_party.length?e.licence.third_party.map(t=>`${esc(t.name)} / ${esc(t.spdx)}<br>${esc(t.source)}`).join('<br>'):'No third-party notices in this manifest.'}</dd><dt>Source repository</dt><dd>${esc(e.source.repo)}</dd><dt>Commit</dt><dd><code>${esc(e.source.commit)}</code></dd><dt>Paths</dt><dd>${e.source.paths.map(esc).join('<br>')}</dd><dt>Subject artifact</dt><dd>${e.subject.artifact?esc(JSON.stringify(e.subject.artifact)):'No binary artifact.'}</dd><dt>Requirements and toolchain</dt><dd>${[...e.requires,e.toolchain].map(esc).join('<br>')}</dd></dl></div></div>`;$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(e.replay.command);$('#copy').textContent='Command copied'}catch{$('#copy').textContent='Select the command above to copy it'}}}
async function select(id){selectedId=id;current=manifests.get(id)||null;$('#selector').value=id;display('READY','Load an input and run a check.','No check submitted for this entry');const summary=entries.find(e=>e.id===id);$('#replay-status').textContent=current?.replay.status==='real'?'Real replay / re-check the bundle':'Recorded replay / not re-run by fvapi';$('#input').value=JSON.stringify(current?.check?.example_input||{},null,2);$('#input-note').textContent=current?.check?'This check does not replace proof replay.':'No checker for this entry. Run check returns 409.';$('#edit').disabled=!current?.check;if(current)renderEvidence(current);else $('#evidence').innerHTML=`<h3>${esc(summary?.title||id)}</h3><p>${esc(summary?.claim||'')}</p><p class="warning">Recorded stub. Not re-run by fvapi. The full manifest is unavailable in this mock.</p>`;draw()}
function openDossier(){$('#dossier').open=true;$('#dossier').scrollIntoView({block:'start'})}
async function logs(mode=logMode){logMode=mode;const r=await api(mode);const data=r.data;$('#log-title').textContent=mode==='answers'?'Returned answers':'Unmatched requests / counts by key';const records=mode==='demand'?data.misses:data.answers;$('#log').innerHTML=(mode==='demand'?`<div class="record"><strong>Counts by key</strong><pre>${esc(JSON.stringify(data.by_key,null,2))}</pre></div>`:'')+(records?.length?records.map(x=>`<div class="record"><pre>${esc(JSON.stringify(x,null,2))}</pre></div>`).join(''):'<p>No records. Run a lookup or a check.</p>');if(mode==='demand'){for(const x of records||[]){const key=x.query?.spec_id||x.spec_id||Object.entries(x.query||{}).map(([k,v])=>k+': '+v).join('; ');if(key&&!misses.includes(key))misses.push(key)}draw()}}
async function lookup(){const q=$('#query').value,r=await api('lookup',{spec_id:q});if(r.ok){matched=r.data.entry_id||r.data.entry?.id||q;await select(matched);display('FOUND','Matched proof path is highlighted.',`Lookup / HTTP ${r.status}`);$('#notice').textContent='Match found. Inspect the proof package and replay it.'}else{matched='';if(r.status===404){if(!misses.includes(q))misses.unshift(q);display('NO MATCH','Logged as demand.',`Lookup / HTTP ${r.status}`);$('#notice').textContent='No match. Logged as demand. Try another specification.'}else $('#notice').textContent=r.data.detail;draw()}await logs()}
async function check(){let value;try{value=JSON.parse($('#input').value)}catch{display('INPUT ERROR','Correct the JSON and run the check again.');return}const r=await api('checks/'+encodeURIComponent(selectedId),value);if(r.ok)display(r.data.verdict.toUpperCase(),r.data.output?.reason||'Inspect the response and re-check locally.',`${r.data.elapsed_ms} ms / ${r.data.ran_on} / exit ${r.data.exit_code}`);else display(r.status===409?'NO CHECKER':'ERROR',r.status===409?'Choose an entry with an input checker.':r.data.detail,`HTTP ${r.status}`);draw();await logs('answers')}
function editWeight(){try{const input=JSON.parse($('#input').value);input.rows[0].weights[0]+=1;$('#input').value=JSON.stringify(input,null,2)}catch{display('INPUT ERROR','Load an example before editing a weight.')}}
function failure(e){display('ERROR','The API could not load. Reload to try again.',e.message);document.body.dataset.error=e.message}
$('#selector').onchange=()=>select($('#selector').value).catch(failure);$('#run').onclick=()=>check().catch(failure);$('#edit').onclick=editWeight;$('#example').onclick=()=>{if(current?.check)$('#input').value=JSON.stringify(current.check.example_input,null,2);else display('NO CHECKER','Choose an entry with an input checker.')};$('#lookup').onsubmit=e=>{e.preventDefault();lookup().catch(failure)};$('#answers').onclick=()=>logs('answers').catch(failure);$('#demand').onclick=()=>logs('demand').catch(failure);$('#inspect').onclick=e=>{e.preventDefault();openDossier()};
(async()=>{entries=(await api('catalog')).data.entries;await Promise.all(entries.map(async e=>{const r=await api('catalog/'+encodeURIComponent(e.id));if(r.ok)manifests.set(e.id,r.data)}));$('#selector').innerHTML=entries.map(e=>`<option value="${esc(e.id)}">${esc(e.id)}</option>`).join('');const checker=[...manifests.values()].find(e=>e.check!=null),recorded=entries.find(e=>e.replay_status==='recorded'&&manifests.has(e.id))||entries.find(e=>e.replay_status==='recorded');const state=new URLSearchParams(location.search).get('state')||'catalog';await select((state==='recorded'||state==='check-409')?(recorded?.id||entries[0].id):(checker?.id||entries[0].id));await logs('demand');await logs('answers');if(state==='lookup-hit'||state==='lookup-miss'){$('#query').value=state==='lookup-hit'?(checker?.id||selectedId):'unmatched.example';await lookup()}if(state.startsWith('check-')){if(state==='check-reject')editWeight();await check()}if(state==='demand')await logs('demand');if(state==='entry'||state==='recorded'){openDossier();if(state==='entry')$('.files details')?.setAttribute('open','')}document.body.dataset.ready='true'})().catch(failure);
